318	// Adam + decoupled WD on smart_grad, with optional lamb-scaled mu blending.
319	__global__ void sg11_adam_decay_kernel(
320	    float* param, float* exp_avg, float* exp_avg_sq,
321	    const float* smart_grad, const float* mu,
322	    float lamb_eff, float beta1, float beta2, float lr,
323	    float wd_eff, float eps, float bc1, float bc2, int64_t N
324	) {
325	    const int64_t stride = prim::grid_stride();
326	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
327	        // g_eff = smart_grad + lamb_eff*mu blending; the bias-corrected Adam +
328	        // decoupled-WD math lives once in algorithms/supergrok11.h.
329	        const float g_eff = ::grokking::sm90::sg_sanitize_grad(smart_grad[i]) +
330	                            lamb_eff * mu[i];
331	        sg11_adam_tail(param, exp_avg, exp_avg_sq, g_eff,
332	                       lr, beta1, beta2, eps, wd_eff, bc1, bc2, i);
333	    }
334	}
335	
336	void launch_sg11_adam_decay(
337	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
338	    torch::Tensor smart_grad, torch::Tensor mu,
339	    float lamb_eff, float beta1, float beta2, float lr,
340	    float wd_eff, float eps, float bc1, float bc2
341	) {
342	    const int64_t N = param.numel();
343	    if (N == 0) return;
344	    auto stream = at::cuda::getCurrentCUDAStream().stream();
345	    const int block = SG_TUNED_BLOCK_SIZE;
346	    const int grid = static_cast<int>(
347	        std::min<int64_t>(65535, (N + block - 1) / block));
348	    sg11_adam_decay_kernel<<<grid, block, 0, stream>>>(
349	        param.data_ptr<float>(), exp_avg.data_ptr<float>(),
350	        exp_avg_sq.data_ptr<float>(),
351	        smart_grad.data_ptr<float>(), mu.data_ptr<float>(),
352	        lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2, N);
353	    SG_LAUNCH_CHECK(stream);
354	}
