356	// SAM perturbation: param += rho_over_norm * grad
357	template <typename ParamT>
358	__global__ void sg11_sam_perturb_kernel(
359	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
360	) {
361	    const int64_t stride = prim::grid_stride();
362	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
363	        float p = static_cast<float>(param[i]);
364	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
365	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
366	    }
367	}
368	
369	void launch_sg11_sam_perturb(
370	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
371	) {
372	    const int64_t N = param.numel();
373	    if (N == 0) return;
374	    auto stream = at::cuda::getCurrentCUDAStream().stream();
375	    const int block = SG_TUNED_BLOCK_SIZE;
376	    const int grid = static_cast<int>(
377	        std::min<int64_t>(65535, (N + block - 1) / block));
378	    AT_DISPATCH_FLOATING_TYPES_AND2(
379	        at::ScalarType::Half, at::ScalarType::BFloat16,
380	        param.scalar_type(), "sg11_sam_perturb", [&] {
381	            sg11_sam_perturb_kernel<scalar_t><<<grid, block, 0, stream>>>(
382	                param.data_ptr<scalar_t>(), grad.data_ptr<scalar_t>(),
383	                rho_over_norm, N);
384	            SG_LAUNCH_CHECK(stream);
385	        });
386	}
