388	// Sharpness restore: param = backup, sharpness = ||sam_grad - normal_grad||
389	template <typename ParamT>
390	__global__ void sg11_sharpness_restore_kernel(
391	    ParamT* param, float* sharpness, const ParamT* backup,
392	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
393	) {
394	    const int64_t stride = prim::grid_stride();
395	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
396	        param[i] = backup[i];
397	        float sg = static_cast<float>(sam_grad[i]);
398	        float ng = static_cast<float>(normal_grad[i]);
399	        float diff = sg - ng;
400	        sharpness[i] = diff * diff;
401	    }
402	}
403	
404	void launch_sg11_sharpness_restore(
405	    torch::Tensor param, torch::Tensor sharpness, torch::Tensor backup,
406	    torch::Tensor sam_grad, torch::Tensor normal_grad
407	) {
408	    const int64_t N = param.numel();
409	    if (N == 0) return;
410	    auto stream = at::cuda::getCurrentCUDAStream().stream();
411	    const int block = SG_TUNED_BLOCK_SIZE;
412	    const int grid = static_cast<int>(
413	        std::min<int64_t>(65535, (N + block - 1) / block));
414	    AT_DISPATCH_FLOATING_TYPES_AND2(
415	        at::ScalarType::Half, at::ScalarType::BFloat16,
416	        param.scalar_type(), "sg11_sharpness_restore", [&] {
417	            sg11_sharpness_restore_kernel<scalar_t>
418	                <<<grid, block, 0, stream>>>(
419	                param.data_ptr<scalar_t>(),
420	                sharpness.data_ptr<float>(),
421	                backup.data_ptr<scalar_t>(),
422	                sam_grad.data_ptr<scalar_t>(),
423	                normal_grad.data_ptr<scalar_t>(), N);
424	            SG_LAUNCH_CHECK(stream);
425	        });
426	}
