160	void launch_supergrok15_step(
161	    torch::Tensor& param,
162	    torch::Tensor& exp_avg,
163	    torch::Tensor& exp_avg_sq,
164	    torch::Tensor& mu_buf,
165	    const torch::Tensor& grad,
166	    const torch::Tensor& sharpness,
167	    const torch::Tensor& phi_W1,
168	    const torch::Tensor& phi_b1,
169	    const torch::Tensor& phi_W2,
170	    float phi_b2,
171	    float rescale,
172	    torch::Tensor& sharp_partial,
173	    float gate_global,
174	    float alpha_base, float alpha_max,
175	    float lr, float beta1, float beta2, float eps, float wd,
176	    float bc1, float bc2
177	) {
178	    const int64_t N = param.numel();
179	    if (N == 0) return;
180	
181	    auto stream = at::cuda::getCurrentCUDAStream().stream();
182	
183	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
184	    prim::L2PersistScope l2(stream,
185	        exp_avg.data_ptr(), exp_avg.nbytes(),
186	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
187	
188	    const int block = SG_TUNED_BLOCK_SIZE;
189	    const int grid = static_cast<int>(
190	        std::min<int64_t>(65535, (N + block - 1) / block));
191	
192	    sharp_partial.zero_();
193	
194	    AT_DISPATCH_FLOATING_TYPES_AND2(
195	        at::ScalarType::Half, at::ScalarType::BFloat16,
196	        grad.scalar_type(), "sg15_sweep_a", [&] {
197	            sg15_sweep_a_kernel<scalar_t><<<grid, block, 0, stream>>>(
198	                mu_buf.data_ptr<float>(),
199	                grad.data_ptr<scalar_t>(),
200	                sharpness.data_ptr<float>(),
201	                phi_W1.data_ptr<float>(),
202	                phi_b1.data_ptr<float>(),
203	                phi_W2.data_ptr<float>(),
204	                phi_b2,
205	                rescale,
206	                sharp_partial.data_ptr<float>(), N);
207	            SG_LAUNCH_CHECK(stream);
208	        });
209	
210	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
211	                          grad.scalar_type() == torch::kFloat32;
212	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
213	        prim::is_vec4_alignable(param.data_ptr(), N) &&
214	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
215	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
216	        prim::is_vec4_alignable(grad.data_ptr(), N) &&
217	        prim::is_vec4_alignable(mu_buf.data_ptr(), N)) {
218	        const int64_t N4 = N / 4;
219	        const int grid4 = static_cast<int>(
220	            std::min<int64_t>(65535, (N4 + block - 1) / block));
221	        sg15_sweep_b_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
222	            reinterpret_cast<float4*>(param.data_ptr<float>()),
223	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
224	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
225	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
226	            reinterpret_cast<const float4*>(mu_buf.data_ptr<float>()),
227	            gate_global, alpha_base, alpha_max,
228	            lr, beta1, beta2, eps, wd, bc1, bc2, N4);
229	        SG_LAUNCH_CHECK(stream);
230	        return;
231	    }
232	
233	    AT_DISPATCH_FLOATING_TYPES_AND2(
234	        at::ScalarType::Half, at::ScalarType::BFloat16,
235	        param.scalar_type(), "sg15_sweep_b", [&] {
236	            sg15_sweep_b_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
237	                <<<grid, block, 0, stream>>>(
238	                param.data_ptr<scalar_t>(),
239	                exp_avg.data_ptr<float>(),
240	                exp_avg_sq.data_ptr<float>(),
241	                grad.data_ptr<scalar_t>(),
242	                mu_buf.data_ptr<float>(),
243	                gate_global, alpha_base, alpha_max,
244	                lr, beta1, beta2, eps, wd, bc1, bc2, N);
245	            SG_LAUNCH_CHECK(stream);
246	        });
247	}
